assert 49-24==25 and 9+20==29 and 29+20==49 and 16-2==14 and 14**2-2==194 and 9+2==11 and 11+2==13
assert 81-52==29 and (100-50)//2==25 and 1005**2==1010025 and 997**2==994009 and 103*97==9991
eq('(2a + 3b − c)²','4a² + 9b² + c² + 12ab − 6bc − 4ac')
