eq('x² + 6x + 8','(x + 3)² − 1'); eq('(a + b)² + (a − b)²','2(a² + b²)')
eq('(3x + 2y)² − (3x − 2y)²','24xy'); eq('(x + y)² + 2(x + y)(x − y) + (x − y)²','4x²'); eq('(a − b)² + 2(a − b)(b − c) + (b − c)²','(a − c)²')
assert (9-2)**2-2==47 and val('(2x + 3)²',x=sp.Rational(7,2))==100 and val('25x² − 30xy + 9y²',x=1,y=2)==1
eq('(x + 5)(x − 3)','(x + 1)² − 16')
