assert sp.expand((x-1)*(x+3))==x**2+2*x-3 and Pv('x**3+2*x**2-4*x+4',1)==3 and Pv('3*x**3-2*x**2+x-4',sp.Rational(2,3))==sp.Rational(-10,3)
assert Pv('4*x**3-3*x+1',sp.Rational(-1,2))==2 and Pv('x**3-7*x+6',1)==0 and Pv('x**3-7*x+6',2)==0
assert Pv('x**3-3*x**2+4*x-10',3)==2 and Pv('x**10+1',-1)==2 and Pv('2*x**2+3*x-5',-3)==4 and Pv('sp.Rational(7,2)*x**3-4*x**2+3*x-8'.replace('sp.',''),2)==10
assert Pv('x**3+2*x**2-x+3',1)==5 and Pv('2*x**3+5*x**2-4*x+1',sp.Rational(1,2))==sp.Rational(1,2) and Pv('x**3+1',sp.Rational(1,2))==sp.Rational(9,8)
